<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_role('admin','staff');$action=$_POST['action']??'';
if($action==='create'){$customer=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['customer_phone']??''));$ids=$_POST['product_id']??[];$qtys=$_POST['quantity']??[];if($customer===''||!is_array($ids)||!is_array($qtys)||count($ids)===0){flash('danger','Nhập tên khách hàng và ít nhất một sản phẩm.');redirect('/orders.php');}
try{$pdo->beginTransaction();$items=[];$total=0;
foreach($ids as $i=>$rawId){$pid=(int)$rawId;$qty=(int)($qtys[$i]??0);if($pid<1||$qty<1)throw new RuntimeException('Sản phẩm hoặc số lượng không hợp lệ.');$st=$pdo->prepare('SELECT id,name,sale_price,stock_qty FROM products WHERE id=? AND is_active=1 FOR UPDATE');$st->execute([$pid]);$p=$st->fetch();if(!$p)throw new RuntimeException('Không tìm thấy sản phẩm.');if((int)$p['stock_qty']<$qty)throw new RuntimeException('Không đủ tồn kho cho '.$p['name']);$items[]=['p'=>$p,'qty'=>$qty];$total+=(float)$p['sale_price']*$qty;}
$code='SO-'.date('ymd-His').'-'.random_int(100,999);$st=$pdo->prepare("INSERT INTO orders(order_code,customer_name,customer_phone,total_amount,status,created_by) VALUES(?,?,?,?, 'completed',?)");$st->execute([$code,$customer,$phone?:null,$total,current_user()['id']]);$orderId=(int)$pdo->lastInsertId();
foreach($items as $it){$p=$it['p'];$qty=$it['qty'];$st=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price,line_total) VALUES(?,?,?,?,?)');$st->execute([$orderId,$p['id'],$qty,$p['sale_price'],$p['sale_price']*$qty]);$st=$pdo->prepare('UPDATE products SET stock_qty=stock_qty-? WHERE id=? AND stock_qty>=?');$st->execute([$qty,$p['id'],$qty]);if($st->rowCount()!==1)throw new RuntimeException('Tồn kho vừa thay đổi, vui lòng thử lại.');$st=$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,quantity,reference_type,reference_id,note,created_by) VALUES(?,'out',?,'order',?,?,?)");$st->execute([$p['id'],$qty,$orderId,'Bán hàng '.$code,current_user()['id']]);}
$pdo->commit();flash('success',"Đã tạo đơn $code và trừ tồn kho.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Không thể tạo đơn: '.$e->getMessage());}redirect('/orders.php');}
if($action==='status'){require_role('admin');$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$st=$pdo->prepare('SELECT status FROM orders WHERE id=?');$st->execute([$id]);$old=$st->fetchColumn();if($old==='pending'&&$status==='cancelled'){$pdo->beginTransaction();try{$st=$pdo->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=?');$st->execute([$id]);foreach($st->fetchAll() as $it){$pdo->prepare('UPDATE products SET stock_qty=stock_qty+? WHERE id=?')->execute([$it['quantity'],$it['product_id']]);$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,quantity,reference_type,reference_id,note,created_by) VALUES(?,'adjustment',?,'order',?,'Hoàn kho do hủy đơn',?)")->execute([$it['product_id'],$it['quantity'],$id,current_user()['id']]);}$pdo->prepare("UPDATE orders SET status='cancelled' WHERE id=?")->execute([$id]);$pdo->commit();flash('success','Đã hủy đơn và hoàn tồn kho.');}catch(Throwable $e){$pdo->rollBack();flash('danger','Không thể hủy đơn.');}}else{flash('warning','Chỉ đơn chờ xử lý mới có thể hủy bằng thao tác này.');}redirect('/orders.php');}}
$products=$pdo->query('SELECT id,sku,name,sale_price,stock_qty FROM products WHERE is_active=1 AND stock_qty>0 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT o.*,u.full_name FROM orders o JOIN users u ON u.id=o.created_by ORDER BY o.id DESC LIMIT 100')->fetchAll();$pageTitle='Đơn hàng';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Đơn hàng bán</h1><p class="text-secondary mb-0">Tạo đơn bán và tự động cập nhật tồn kho bằng transaction.</p></div></div><div class="card mb-4"><div class="card-body"><h2 class="h5">Tạo đơn hàng nhanh</h2><form method="post" id="orderForm"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="row g-3"><div class="col-12 col-md-4"><label class="form-label">Tên khách hàng</label><input name="customer_name" class="form-control" required></div><div class="col-12 col-md-3"><label class="form-label">Điện thoại</label><input name="customer_phone" class="form-control"></div><div class="col-12 col-md-5"><label class="form-label">Sản phẩm</label><select name="product_id[]" class="form-select" required><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['sku'].' · '.$p['name'].' — '.money($p['sale_price']).' (tồn '.$p['stock_qty'].')')?></option><?php endforeach;?></select></div><div class="col-6 col-md-3"><label class="form-label">Số lượng</label><input type="number" min="1" name="quantity[]" class="form-control" value="1" required></div><div class="col-12 col-md-4 d-flex align-items-end"><button class="btn btn-primary">Tạo đơn và trừ kho</button></div></div><p class="small text-secondary mt-2 mb-0">Bản demo tạo đơn với một dòng sản phẩm; có thể mở rộng nhiều dòng hàng bằng JavaScript.</p></form></div></div>
<div class="card"><div class="card-body"><h2 class="h5 mb-3">Danh sách đơn hàng gần đây</h2><div class="table-responsive"><table class="table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày tạo</th><th>Tổng tiền</th><th>Trạng thái</th><th>Người tạo</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['order_code'])?></td><td><?=e($r['customer_name'])?><div class="small text-secondary"><?=e($r['customer_phone'])?></div></td><td><?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></td><td><?=money($r['total_amount'])?></td><td><span class="badge text-bg-<?=$r['status']==='completed'?'success':($r['status']==='cancelled'?'danger':'warning')?>"><?=e(['pending'=>'Chờ xử lý','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'][$r['status']]??$r['status'])?></span></td><td><?=e($r['full_name'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
